import {fmt,esc,initials,pressureState,selectPlayers,reliabilityIndex,csvFor} from './lib.js';
import {createSelectionRoom} from './auction.js';
import {playerAvatar,portrait,imageCredits} from './photos.js';

const main=document.querySelector('main'), dialog=document.querySelector('#player-dialog');
const state={role:'bat',query:'',scope:'top',sort:'rank',page:1,compareRole:'bat',compareA:'2984',compareB:'3647',labRole:'bat',probability:45,balls:48,wins:18,appearances:28};
let data, route='overview', returnFocus, room, revealObserver;
const titles={overview:'Overview',auction:'Selection room',rankings:'Player rankings',compare:'Compare players',lab:'Pressure lab',robustness:'Method & robustness'};
const signed=n=>`${n>=0?'+':''}${fmt(n)}`;
const player=(id,role)=>data.players.find(p=>p.id===String(id)&&p.role===role);
const roleName=role=>role==='bat'?'Batters':'Bowlers';
const roleClass=role=>role==='bowl'?'bowl':'bat';
const idKey=p=>`${p.role}:${p.id}`;
const avatar=playerAvatar;
const head=(label,title,sub)=>`<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><span class="date-pill">2022–2026 · Supplied data pack</span></div>`;
const segment=(id,current)=>`<div class="segmented" id="${id}" aria-label="Player role"><button data-role="bat" class="${current==='bat'?'active pink':''}" aria-pressed="${current==='bat'}">Batters</button><button data-role="bowl" class="${current==='bowl'?'active blue':''}" aria-pressed="${current==='bowl'}">Bowlers</button></div>`;
const kohliNote=`Virat Kohli is eligible and ranked #99 of 117 batters in this method. Two notable innings—82* vs Pakistan in 2022 and 76 in the 2024 World Cup final—are absent from the supplied match inventory. This is a dataset-specific result, not a verdict on his career.`;
const sources=()=>data.missingFixtures.map(f=>`<div class="coverage-item"><h3>${esc(f.date)} · ${esc(f.opponent)}</h3><p>${esc(f.description)} This fixture is absent from the supplied matches.csv inventory.</p><a class="source-link" href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">Official ICC match coverage ↗</a></div>`).join('');
function leader(p){return `<button class="leader" data-player="${idKey(p)}" aria-label="View ${esc(p.name)}, rank ${p.rank}"><span class="rank-num ${p.rank<=3?'top':''}">${String(p.rank).padStart(2,'0')}</span>${avatar(p)}<span class="leader-main"><span class="leader-name">${esc(p.shortName)}</span><span class="leader-sub">${p.wins} / ${p.n} positive pressure appearances</span></span><span class="leader-score">${fmt(p.score)}<span class="score-track"><span style="width:${p.score}%"></span></span></span></button>`;}
function overview(){
  return `${head('The pressure-performance study','A closer look at the clutch.','An evidence-led view of the players who delivered when the match tightened.')}<section class="hero" aria-label="Pressure study introduction"><div><div class="eyebrow">20 PICKS. ONE TRANSPARENT METHOD.</div><h2>Big moments.<br><em>Beyond big names.</em></h2><p>Separate reputation from repeatability. Explore late-innings pressure performance across the full supplied player pool.</p><a class="button button-pink" href="#rankings">Explore the final twenty <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><svg class="pitch-graphic" viewBox="0 0 340 250"><defs><radialGradient id="pitchFade"><stop stop-color="#213064"/><stop offset="1" stop-color="#172045"/></radialGradient><filter id="glow"><feGaussianBlur stdDeviation="5"/></filter></defs><ellipse cx="168" cy="128" rx="134" ry="99" fill="url(#pitchFade)" stroke="#ffffff12"/><ellipse cx="168" cy="128" rx="103" ry="76" fill="none" stroke="#ffffff12" stroke-dasharray="3 5"/><ellipse cx="168" cy="128" rx="64" ry="48" fill="none" stroke="#ffffff0b"/><g transform="rotate(-25 168 128)"><rect x="151" y="80" width="34" height="96" rx="3" fill="#273766" stroke="#556083"/><path d="M147 94h42m-42 68h42m-34-77v12m9-12v12m9-12v12m-18 64v12m9-12v12m9-12v12" stroke="#a5afcf" stroke-width="1.3"/></g><path d="M65 176Q237 180 245 56" fill="none" stroke="#e779b1" stroke-width="1.5" stroke-dasharray="4 5"/><circle class="ball-glow" cx="245" cy="56" r="12" fill="#f778b5" opacity=".5" filter="url(#glow)"/><circle cx="245" cy="56" r="5.5" fill="#ff8fc4"/><path d="m243 52 2 7" stroke="#fff" stroke-width="1"/><circle cx="65" cy="176" r="4" fill="#dec28a"/><g fill="#9eafd5"><circle cx="90" cy="96" r="3"/><circle cx="257" cy="157" r="3"/><circle cx="145" cy="212" r="3"/><circle cx="215" cy="205" r="3"/></g><path d="M280 100h18m-9-9v18" stroke="#d3b77f" opacity=".6"/></svg><span class="art-label top">CONTEXT → PERFORMANCE</span><span class="art-label bottom">ILLUSTRATIVE FIELD · NOT MATCH DATA</span></div></section>
  <section class="stats-grid" aria-label="Study coverage">${[['Audited matches','797','Whole-fixture quality filtering','◫'],['Retained events','1,90,480','From 2,00,999 source events','⋮'],['Supported player roles','249','117 batters · 132 bowlers','♙'],['Final selections','20','10 batters · 10 bowlers','✧']].map(([label,value,note,icon])=>`<article class="stat"><div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div><span class="stat-icon" aria-hidden="true">${icon}</span></article>`).join('')}</section>
  <div class="section-line"><div><h2>Leading under pressure</h2><p>Top five in each role · index on a 0–100 scale</p></div><a class="text-link" href="#rankings">View all rankings <span>↗</span></a></div><section class="grid-two">${['bat','bowl'].map(role=>`<article class="card ${roleClass(role)}"><div class="card-head"><h3><span class="role-icon" aria-hidden="true">${role==='bat'?'╱':'◉'}</span>${roleName(role)}</h3><span class="tag">TOP 5 / ${role==='bat'?'117':'132'}</span></div><div class="mini-legend"><span>OFFICIAL RANK · PLAYER</span><span>RELIABILITY INDEX</span></div>${selectPlayers(data.players,{role}).slice(0,5).map(leader).join('')}<div class="leader-more"><span>Context-adjusted · uncertainty penalised</span><button class="text-link" data-open-role="${role}">Full top ten ↗</button></div></article>`).join('')}</section>
  <aside class="callout"><span class="callout-icon" aria-hidden="true">ⓘ</span><div><h3>Where is Virat Kohli? Start with the coverage.</h3><p>Rankings describe this sample and definition of pressure. Two of his landmark World Cup innings are absent.</p></div><button class="text-link" data-player="bat:47">Inspect the evidence ↗</button></aside><p class="note">The index is a conservative statistical score, not a predicted success percentage. These are historical performance rankings; auction availability and nationality are not selection filters. <a href="#robustness" class="source-link">Read the assumptions.</a></p>`;
}
function rankings(){return `${head('The final selections','Evidence over reputation.','Inspect the official top ten, or search the full supported cohort. Changing a view never changes the official rank.')}<div class="toolbar">${segment('rank-role',state.role)}<div class="search-wrap"><span aria-hidden="true">⌕</span><label class="sr-only" for="player-search">Search player name</label><input id="player-search" type="search" placeholder="Search any supported player…" value="${esc(state.query)}" autocomplete="off"></div><label class="sr-only" for="cohort">Player cohort</label><select id="cohort" class="control-select"><option value="top" ${state.scope==='top'?'selected':''}>Final top 10</option><option value="all" ${state.scope==='all'?'selected':''}>Full supported cohort</option></select><label class="sr-only" for="sort">Sort view</label><select id="sort" class="control-select">${[['rank','Official rank'],['sample','Most appearances'],['lift','Highest own-usual lift'],['utility','Highest net utility']].map(([v,t])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t}</option>`).join('')}</select><button class="button button-outline" id="export-csv">Export CSV ↓</button></div><section class="card table-card ${roleClass(state.role)}" id="rank-table" aria-label="Player rankings"></section><div class="notice"><strong>What counts as a positive appearance?</strong> The player’s summed contextual utility residual across that fixture’s valid pressure events is greater than zero. A zero is counted as non-positive. The index uses an equal Beta(4,4) prior for every supported player.</div><p class="note">Pressure exposure: non-wide striker events for batters; legal deliveries for bowlers. Index ties use posterior mean, then pooled pressure utility, then player ID. Full-pool selection follows the organizer’s clarification, with no IPL eligibility restriction.</p>`;}
function renderTable(){
  const list=selectPlayers(data.players,state), pageSize=15, pages=Math.max(1,Math.ceil(list.length/pageSize));state.page=Math.min(state.page,pages);
  const visible=list.slice((state.page-1)*pageSize,state.page*pageSize);
  document.querySelector('#rank-table').className=`card table-card ${roleClass(state.role)}`;
  document.querySelector('#rank-table').innerHTML=`<div class="table-summary"><span role="status">${list.length} ${roleName(state.role).toLowerCase()} · ${state.scope==='top'?'official top ten':'supported cohort'}${state.query?' · search applied':''}</span><span>Index points ≠ win probability</span></div><div class="table-scroll"><table><thead><tr><th scope="col">Rank</th><th scope="col">Player</th><th scope="col">Index ↓</th><th scope="col">Positive / total</th><th scope="col">Pressure exposure</th><th scope="col">Own-usual lift</th><th scope="col">Net utility / 100</th><th scope="col"><span class="sr-only">Details</span></th></tr></thead><tbody>${visible.map((p,i)=>`<tr style="--i:${i}"><td><span class="official-rank ${p.rank<=10?'selected-rank':''}">${String(p.rank).padStart(2,'0')}</span></td><td><button class="table-player" data-player="${idKey(p)}">${avatar(p)}<span>${esc(p.shortName)}<small>${p.rank<=10?'Final selection':'Supported cohort'}</small></span></button></td><td class="table-score">${fmt(p.score,2)}</td><td>${p.wins} <span style="color:var(--muted)">/ ${p.n}</span></td><td>${fmt(p.exposure,0)}</td><td class="${p.lift>=0?'positive':'negative'}">${signed(p.lift)} pp</td><td>${signed(p.utility)}</td><td><button class="text-link" data-player="${idKey(p)}" aria-label="Inspect ${esc(p.name)}">↗</button></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No supported players match this search. Try another name or clear the search.</div>':''}</div><div class="pagination"><span>${list.length?`${(state.page-1)*pageSize+1}–${Math.min(state.page*pageSize,list.length)} of ${list.length}`:'0 results'}</span><div><button class="button button-outline compact" data-page="-1" ${state.page===1?'disabled':''}>← Previous</button><button class="button button-outline compact" data-page="1" ${state.page>=pages?'disabled':''}>Next →</button></div></div>`;
}
function compare(){return `${head('Player versus player','Make the comparison fair.','Same role. Same method. Different samples. Read the uncertainty alongside the headline score.')}<div class="toolbar">${segment('compare-role',state.compareRole)}</div><section class="card"><div class="compare-picker"><label>PLAYER A<select class="control-select" id="compare-a">${compareOptions(state.compareA)}</select></label><span class="versus">VS</span><label>PLAYER B<select class="control-select" id="compare-b">${compareOptions(state.compareB)}</select></label></div><div class="comparison-controls"><span class="tag" style="border:0;background:none;padding-left:0">QUICK COMPARE</span><button class="tag" data-pair="bat:2984:3647">Raza / Iyer</button><button class="tag" data-pair="bowl:7327:2933">Rasikh / Bumrah</button><button class="tag" data-pair="bat:47:7897">Kohli / Tilak</button></div><div id="compare-results"></div></section><div class="notice"><strong>A higher score is not proof of a better career.</strong> The index rewards repeatability relative to match context and penalises limited evidence. Own-usual lift asks a different question: did this player improve versus their ordinary-state baseline?</div>`;}
function compareOptions(selected){return selectPlayers(data.players,{role:state.compareRole,scope:'all'}).map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>#${p.rank} · ${esc(p.shortName)}</option>`).join('');}
function renderCompare(){
  const a=player(state.compareA,state.compareRole),b=player(state.compareB,state.compareRole);
  const row=(label,av,bv,an='',bn='')=>`<div class="compare-row"><div class="compare-value">${av}${an?`<small>${an}</small>`:''}</div><div class="compare-label">${label}</div><div class="compare-value">${bv}${bn?`<small>${bn}</small>`:''}</div></div>`;
  document.querySelector('#compare-results').innerHTML=`<div class="comparison-header">${[a,b].map(p=>`<div class="compare-person">${avatar(p)}<div><h3>${esc(p.shortName)}</h3><p>Official rank #${p.rank} · ${roleName(p.role).toLowerCase()}</p></div></div>`).join('')}</div>${row('Reliability index',fmt(a.score,2),fmt(b.score,2),'0–100 points','0–100 points')}${row('Pressure positives',`${a.wins} / ${a.n}`,`${b.wins} / ${b.n}`,'fixture appearances','fixture appearances')}${row('Own-usual lift',`${signed(a.lift)} pp`,`${signed(b.lift)} pp`)}${row('Net pressure utility / 100',signed(a.utility),signed(b.utility),'context-adjusted','context-adjusted')}${row('Conditional 80% rank interval',`${fmt(a.rankLow,0)}–${fmt(a.rankHigh,0)}`,`${fmt(b.rankLow,0)}–${fmt(b.rankHigh,0)}`,'fixture bootstrap','fixture bootstrap')}${row('Pressure exposure',fmt(a.exposure,0),fmt(b.exposure,0))}<div class="compare-bars">${[a,b].map(p=>`<div><div class="rate-heading">${esc(p.shortName)} · smoothed positive rate</div>${[['Pressure',p.pRate,false],['Ordinary states',p.ordinaryRate,true]].map(([name,val,ordinary])=>`<div class="rate-item"><div><span>${name}</span><strong>${fmt(val*100)}%</strong></div><div class="wide-track ${ordinary?'ordinary':''}"><span style="width:${val*100}%"></span></div></div>`).join('')}</div>`).join('')}</div><p class="note">Rates use the same Beta(4,4) smoothing. Rank intervals are conditional on the fitted model, labels and eligible cohort; they do not include all sources of uncertainty.</p><div class="comparison-controls"><button class="text-link" data-player="${idKey(a)}">Inspect ${esc(a.shortName)} ↗</button><button class="text-link" data-player="${idKey(b)}">Inspect ${esc(b.shortName)} ↗</button></div>`;
}
function lab(){return `${head('Explore the definition','Pressure, without the guesswork.','Two interactive sandboxes make the method inspectable. Illustrations here do not change the official rankings.')}<div class="grid-two"><section class="card"><h2 class="panel-title">01 / Is this a pressure event?</h2><p class="panel-sub">Set the pre-delivery batting-side win proxy and the balls remaining, then choose whose perspective to evaluate.</p><div class="field">${segment('lab-role',state.labRole)}</div><div class="field"><div class="field-top"><label for="probability">Batting-side win proxy</label><output id="probability-value" for="probability">${state.probability}%</output></div><input class="range" id="probability" type="range" min="0" max="100" step="1" value="${state.probability}"><div class="range-labels"><span>0% · unlikely</span><span>100% · likely</span></div></div><div class="field"><div class="field-top"><label for="balls">Balls remaining</label><output id="balls-value" for="balls">${state.balls}</output></div><input class="range" id="balls" type="range" min="1" max="120" step="1" value="${state.balls}"><div class="range-labels"><span>1 ball</span><span>120 balls</span></div></div><div class="preset-row"><button data-state-preset="45:48">Contested finish</button><button data-state-preset="45:72">Earlier innings</button><button data-state-preset="85:10">Final two overs</button></div><div id="pressure-result" aria-live="polite"></div><div class="formula"><code>20% ≤ side proxy ≤ 65% &amp; balls ≤ 60<br>OR 10% ≤ side proxy ≤ 90% &amp; balls ≤ 12</code><br>Bowling-side proxy = 1 − batting-side proxy. All boundaries are inclusive.</div></section><section class="card"><h2 class="panel-title">02 / Why does sample size matter?</h2><p class="panel-sub">The index is the 10th percentile of Beta(positives + 4, non-positives + 4), multiplied by 100. A high observed rate alone is not enough.</p><div class="field"><div class="field-top"><label for="appearances">Pressure appearances</label><output id="appearances-value" for="appearances">${state.appearances}</output></div><input class="range" id="appearances" type="range" min="1" max="100" value="${state.appearances}"></div><div class="field"><div class="field-top"><label for="wins">Positive appearances</label><output id="wins-value" for="wins">${state.wins}</output></div><input class="range" id="wins" type="range" min="0" max="${state.appearances}" value="${state.wins}"></div><div class="preset-row"><button data-index-preset="18:28">Raza · 18/28</button><button data-index-preset="12:13">Rasikh · 12/13</button><button data-index-preset="9:26">Kohli · 9/26</button></div><div class="sandbox-number" id="sandbox-score" aria-live="polite"></div><p class="panel-sub">CONSERVATIVE RELIABILITY INDEX</p><div class="formula" id="sandbox-explain"></div><p class="note">This explains the score formula only. Official eligibility also requires overall, pressure and recent exposure support. A sandbox score does not make a player eligible.</p></section></div><aside class="callout"><span class="callout-icon" aria-hidden="true">◎</span><div><h3>Match state is a proxy for pressure.</h3><p>The model does not observe a player’s emotions, intent or psychological stress. It evaluates performance in a declared set of late-innings situations.</p></div></aside>`;}
function renderPressure(){const r=pressureState(state.probability/100,state.balls,state.labRole);document.querySelector('#probability-value').textContent=`${state.probability}%`;document.querySelector('#balls-value').textContent=state.balls;document.querySelector('#pressure-result').innerHTML=`<div class="result-state ${r.pressure?'pressure-on':''}"><div class="eyebrow">${state.labRole==='bat'?'BATTING':'BOWLING'} PERSPECTIVE · ${fmt(r.side*100,0)}% SIDE PROXY</div><div class="state-title">${r.pressure?'Pressure event.':'Outside the mask.'}</div><p class="state-detail">${esc(r.reason)} · ${state.balls} balls remaining</p></div>`;}
function renderSandbox(){document.querySelector('#appearances-value').textContent=state.appearances;document.querySelector('#wins-value').textContent=state.wins;document.querySelector('#wins').max=state.appearances;document.querySelector('#wins').value=state.wins;document.querySelector('#sandbox-score').innerHTML=`${fmt(reliabilityIndex(state.wins,state.appearances),2)}<span>/ 100</span>`;document.querySelector('#sandbox-explain').innerHTML=`Observed positive rate: <strong>${fmt(100*state.wins/state.appearances)}%</strong><br>Smoothed positive rate: <strong>${fmt(100*(state.wins+4)/(state.appearances+8))}%</strong><br>Lower-tail index uses Beta(${state.wins+4}, ${state.appearances-state.wins+4}). The conservative score is below the smoothed rate.`;}
function robustness(){return `${head('Behind every rank','Show the work. Own the limits.','An auditable chain from pre-delivery context to a conservative ranking—with the sensitivity visible.')}<section class="card"><div class="section-line"><div><h2>How the ranking is built</h2><p>One common framework, applied consistently across the supplied pool.</p></div><span class="status-pill">FULL-POOL METHOD v3</span></div><div class="method-steps">${[['01','Define pressure','Use the pre-delivery side-win proxy and balls remaining. The first ten overs are outside the primary mask.'],['02','Adjust for context','Subtract contextual expected utility from player utility. Runs, wickets and delivery attribution follow the declared scoring rules.'],['03','Aggregate by fixture','Sum residuals over each player’s valid pressure events. An appearance is positive only when that sum is above zero.'],['04','Penalise uncertainty','Rank supported players by the 10th percentile of Beta(w + 4, n − w + 4), scaled to 100.']].map(([n,h,p])=>`<div class="method-step"><div class="step-number">${n} /</div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section><div class="grid-two margin-top"><section class="card"><h2 class="panel-title">How much does the top ten move?</h2><p class="panel-sub">Overlap with the primary ten when one analytical choice changes. Low overlap signals dependence on the definition.</p><div class="robust-legend"><span><i class="legend-dot"></i>Batters</span><span><i class="legend-dot blue"></i>Bowlers</span><span>Players retained / 10</span></div>${data.robustness.map(r=>`<div class="robust-row"><div><span>${esc(r.label)}</span><strong>${r.bat} / ${r.bowl}</strong></div><div class="robust-bars"><div class="robust-track"><span style="width:${r.bat*10}%"></span></div><div class="robust-track"><span style="width:${r.bowl*10}%"></span></div></div></div>`).join('')}<p class="note">The IPL-only and recent-only analyses are alternate samples, not eligibility requirements. “Insufficient support” is shown in individual profiles when a scenario cannot support a player.</p></section><section class="card"><h2 class="panel-title">What the analysis can support</h2><dl class="definition-list"><div><dt>Historical repeatability, within a stated sample</dt><dd>This ranks contextual positives in defined late-innings states. It does not establish a universal clutch trait or predict auction value.</dd></div><div><dt>Conditional stability, not complete uncertainty</dt><dd>500 whole-fixture bootstrap resamples; seed 20261116. Models, labels and the eligible cohort stay fixed. Top-ten frequencies are resampling frequencies, not future probabilities.</dd></div><div><dt>Retrospective cross-fitting</dt><dd>Whole matches are held out, but training folds may contain later years. This is not independent validation on future seasons.</dd></div><div><dt>Meaningful definition sensitivity</dt><dd>State-rule and IPL-only changes materially alter the batting list. The final ten should be defended as method-specific selections.</dd></div></dl><div class="formula"><strong>Wicket valuation also matters.</strong><br>At 0.5× wicket value, top-ten overlap is 4 batters / 7 bowlers. At 1.5× it is 4 / 8, conditional on the primary cohort.</div></section></div><section class="card prose-card"><h2>The Kohli check: coverage before conclusions</h2><p class="panel-sub">${kohliNote}</p><div class="coverage-list">${sources()}</div><div class="comparison-controls"><button class="text-link" data-player="bat:47">Inspect Kohli’s complete profile ↗</button></div><p class="note">Adding only a famous player’s missing innings would bias the comparison. A broader study would need consistent, documented augmentation across all players, then a full rerun.</p></section><section class="card prose-card"><h2>Audit notes & precise definitions</h2><details open><summary>Coverage and quality filtering</summary><p>200,999 source events across 867 played-match IDs. Metadata lists 883 fixtures, including 16 without ball events. Whole-fixture quality checks retain 797 matches and 190,480 events; 70 fixtures are excluded. The audit handles 38 super-over events separately. Retained coverage: IPL 352 fixtures, T20Is 416, Emerging competitions 29. Original input files were hash-verified; the raw pack is not included in this dashboard.</p></details><details><summary>Eligibility support thresholds</summary><p>At least 60 pressure-exposure units over 8 positive-exposure fixtures; at least 200 overall-exposure units; at least 20 pressure-exposure units over 3 fixtures since 2025; at least 8 valid pressure appearances. The full evaluated pool contains 880 batting and 640 bowling player-role records; 117 and 132 respectively meet support. A player-role record is not a unique person.</p></details><details><summary>Utility, extras and appearance attribution</summary><p>Batting utility is batter runs minus the declared credited-dismissal wicket cost. Bowling utility is credited wicket value minus attributable runs. Expected utility is contextual and training-derived; wicket costs come from a remaining-runs surface clipped to 0–20. Batting exposure counts non-wide striker events; bowling exposure counts legal deliveries. Illegal-delivery costs can accrue without time exposure. Secondary extras code 35 is excluded from individual bowling credit. A fixture segment with any valid pressure event contributes an appearance, including a short or zero-exposure segment. Zero summed residual counts as non-positive.</p></details><details><summary>Index ties and own-usual lift</summary><p>Exact index ties use posterior mean, then pooled pressure utility per 100 exposure, then lexical player ID. Raza and Iyer both have 18 positives in 28 appearances; Raza leads on pooled utility (26.33 versus 20.64). Overton and Malinga both have 11/14; Overton leads on pooled utility (50.10 versus 40.29). Own-usual lift is the difference between smoothed pressure and ordinary-state positive rates. Negative lift does not exclude a player: the official score measures pressure reliability, a different question.</p></details><details><summary>Selection scope and submission ownership</summary><p>The organizer clarified that Round 1 asks for the top 10 pressure batters and bowlers, rather than retention or auction recommendations. Nationality, IPL participation and auction availability do not filter these rankings. This is an independent participant entry, with no official endorsement. The participant must understand, verify and own the submitted rationale under the competition’s AI-use rules.</p></details><p class="note">The downloadable report preserves the verified final list. This dashboard adds an explicit coverage note for the two missing World Cup fixtures, which is not included in that earlier PDF.</p></section>`;}
function openPlayer(key){
  const [role,id]=key.split(':'),p=player(id,role);if(!p)return;
  returnFocus=document.activeElement;
  const beta=`${fmt(p.betaLow*100)}–${fmt(p.betaHigh*100)}%`;
  document.querySelector('#dialog-content').innerHTML=`<div class="player-dialog-body ${roleClass(role)}"><div class="dialog-top"><div><div class="dialog-role">${roleName(role)} · ${p.rank<=10?'Final selection':'Supported cohort'}</div><h2 id="dialog-title">${esc(p.shortName)}</h2><p>Official rank #${p.rank} / ${role==='bat'?'117':'132'} · ${esc(p.name)}</p></div><button class="icon-button" id="close-dialog" aria-label="Close player details">×</button></div><div class="dialog-score"><strong>${fmt(p.score,2)}</strong><div><p>Conservative reliability index</p><small>10th posterior percentile × 100. Index points are not a predicted success percentage.</small></div></div><div class="mini-grid">${[[`${p.wins} / ${p.n}`,'Positive pressure appearances'],[`${signed(p.lift)} pp`,'Smoothed own-usual lift'],[signed(p.utility),'Net pressure utility / 100']].map(([v,t])=>`<div class="mini-stat"><strong>${v}</strong><small>${t}</small></div>`).join('')}</div><dl class="definition-list"><div><dt>Pressure versus ordinary-state evidence</dt><dd>Pressure: ${p.wins}/${p.n} positives; smoothed rate ${fmt(p.pRate*100)}%. Ordinary states: ${p.ordinaryWins}/${p.ordinaryN}; smoothed rate ${fmt(p.ordinaryRate*100)}%. Conditional 80% beta interval for the pressure rate: ${beta}.</dd></div><div><dt>Exposure & recency</dt><dd>${fmt(p.exposure,0)} pressure-exposure units; ${fmt(p.overallExposure,0)} overall. IPL pressure exposure: ${fmt(p.iplExposure,0)}. Since 2025: ${fmt(p.recentExposure,0)} pressure-exposure units in ${p.recentMatches} fixtures.</dd></div><div><dt>Conditional fixture-bootstrap stability</dt><dd>Top-ten frequency: ${fmt(p.top10Frequency*100)}% of resamples. 80% rank interval: ${fmt(p.rankLow,1)}–${fmt(p.rankHigh,1)}. These are conditional on the fitted models, fixed event labels and fixed cohort.</dd></div></dl><h3 class="panel-title margin-top">Alternate definitions & samples</h3><div class="dialog-scenarios">${p.scenarios.map(s=>`<div>${esc(s.label)}<small>${s.rank!==null?`Alternate rank #${s.rank}`:esc(s.status)}</small></div>`).join('')}</div>${p.id==='47'&&role==='bat'?`<div class="notice"><strong>Read this result in context.</strong> ${kohliNote}</div><div class="coverage-list">${sources()}</div>`:''}<p class="dialog-source">An alternate rank is a separate analysis, not the official ordering. Pressure masks exclude the first ten overs. Dataset coverage, role, support and model choices affect every interpretation.</p><div class="comparison-controls"><button class="button button-dark compact" data-compare-player="${idKey(p)}">Compare this player ↗</button><button class="button button-outline compact" id="dialog-done">Done</button></div></div>`;
  document.querySelector('.dialog-top').insertAdjacentHTML('afterbegin',portrait(p,{className:'dialog-portrait',loading:'eager'}));
  dialog.showModal();document.querySelector('#close-dialog').focus();
}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),2600);}
function setRole(kind,role){
  if(kind==='rank'){state.role=role;state.page=1;render();}
  if(kind==='compare'){state.compareRole=role;const picks=selectPlayers(data.players,{role});state.compareA=picks[0].id;state.compareB=picks[1].id;render();}
  if(kind==='lab'){state.labRole=role;document.querySelectorAll('#lab-role button').forEach(b=>{b.className=b.dataset.role===role?`active ${role==='bat'?'pink':'blue'}`:'';b.setAttribute('aria-pressed',String(b.dataset.role===role));});renderPressure();}
}
function bindRoute(){
  if(route==='auction')room.bind();
  if(route==='rankings'){
    renderTable();document.querySelector('#player-search').addEventListener('input',e=>{state.query=e.target.value;if(state.query.trim())state.scope='all';document.querySelector('#cohort').value=state.scope;state.page=1;renderTable();});
    document.querySelector('#cohort').addEventListener('change',e=>{state.scope=e.target.value;state.page=1;renderTable();});
    document.querySelector('#sort').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;renderTable();});
    document.querySelector('#export-csv').addEventListener('click',()=>{const list=selectPlayers(data.players,state),url=URL.createObjectURL(new Blob([csvFor(list)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`SupeRR_${state.role}_${state.scope}_derived_rankings.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${list.length} derived player records`);});
  }
  if(route==='compare'){renderCompare();for(const letter of ['a','b'])document.querySelector(`#compare-${letter}`).addEventListener('change',e=>{state[`compare${letter.toUpperCase()}`]=e.target.value;renderCompare();});}
  if(route==='lab'){
    renderPressure();renderSandbox();
    for(const field of ['probability','balls'])document.querySelector(`#${field}`).addEventListener('input',e=>{state[field]=Number(e.target.value);renderPressure();});
    for(const field of ['appearances','wins'])document.querySelector(`#${field}`).addEventListener('input',e=>{state[field]=Number(e.target.value);state.wins=Math.min(state.wins,state.appearances);renderSandbox();});
  }
}
function render(){
  room?.cleanup();
  route=location.hash.slice(1).split('?')[0];if(!titles[route])route='overview';
  document.querySelector('#breadcrumb').textContent=titles[route];document.title=`${titles[route]} · SupeRR Pressure Lab`;
  document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===route);if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  main.innerHTML=({overview:()=>overview().replace('<div class="section-line">',`${room.teaser()}<div class="section-line">`),auction:()=>room.render(),rankings,compare,lab,robustness})[route]();main.classList.remove('page-enter');void main.offsetWidth;main.classList.add('page-enter');bindRoute();mountReveals();
}
function mountReveals(){
  revealObserver?.disconnect();
  if(isMotionReduced()||!('IntersectionObserver' in window))return;
  revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-revealed');revealObserver.unobserve(entry.target);}},{threshold:.08});
  main.querySelectorAll('.stat,.room-teaser,.grid-two>.card,.callout,.review-desk,.prose-card').forEach((el,i)=>{el.classList.add('will-reveal');el.style.setProperty('--reveal-delay',`${i%4*45}ms`);revealObserver.observe(el);});
}
function comparePlayer(key){const [role,id]=key.split(':');state.compareRole=role;state.compareA=id;state.compareB=selectPlayers(data.players,{role}).find(p=>p.id!==id).id;if(location.hash==='#compare')render();else location.hash='compare';}
document.addEventListener('click',e=>{
  if(e.target.closest('[data-photo-credits]')){returnFocus=document.activeElement;document.querySelector('#dialog-content').innerHTML=imageCredits();dialog.showModal();document.querySelector('#close-dialog').focus();return;}
  const p=e.target.closest('[data-player]');if(p){openPlayer(p.dataset.player);return;}
  const open=e.target.closest('[data-open-role]');if(open){state.role=open.dataset.openRole;state.scope='top';state.query='';state.page=1;if(location.hash==='#rankings')render();else location.hash='rankings';return;}
  const rb=e.target.closest('[data-role]');if(rb){const container=rb.closest('.segmented');if(container)setRole(container.id.split('-')[0],rb.dataset.role);return;}
  const page=e.target.closest('[data-page]');if(page&&!page.disabled){state.page+=Number(page.dataset.page);renderTable();return;}
  const pair=e.target.closest('[data-pair]');if(pair){const [role,a,b]=pair.dataset.pair.split(':');state.compareRole=role;state.compareA=a;state.compareB=b;render();return;}
  const pr=e.target.closest('[data-state-preset]');if(pr){const [p,b]=pr.dataset.statePreset.split(':').map(Number);state.probability=p;state.balls=b;document.querySelector('#probability').value=p;document.querySelector('#balls').value=b;renderPressure();return;}
  const index=e.target.closest('[data-index-preset]');if(index){[state.wins,state.appearances]=index.dataset.indexPreset.split(':').map(Number);document.querySelector('#appearances').value=state.appearances;renderSandbox();return;}
  if(e.target.closest('#close-dialog,#dialog-done'))dialog.close();
  const cp=e.target.closest('[data-compare-player]');if(cp){dialog.close();comparePlayer(cp.dataset.comparePlayer);}
});
document.addEventListener('error',e=>{if(e.target.matches?.('[data-player-photo]')){e.target.style.display='none';e.target.parentElement.classList.add('photo-failed');}},true);
dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();});
let dark=false;try{dark=localStorage.getItem('rr-theme')==='dark';}catch{}
function applyTheme(){document.body.classList.toggle('dark',dark);document.querySelector('#theme-toggle').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);}
applyTheme();document.querySelector('#theme-toggle').addEventListener('click',()=>{dark=!dark;applyTheme();try{localStorage.setItem('rr-theme',dark?'dark':'light');}catch{}});
const systemMotion=matchMedia('(prefers-reduced-motion: reduce)');let motionPaused=false;
try{motionPaused=localStorage.getItem('rr-motion')==='paused';}catch{}
const isMotionReduced=()=>motionPaused||systemMotion.matches;
function applyMotion(){const reduced=isMotionReduced(),button=document.querySelector('#motion-toggle');document.body.classList.toggle('motion-paused',reduced);button.setAttribute('aria-pressed',String(reduced));button.setAttribute('aria-label',systemMotion.matches?'Reduced motion follows your device setting':reduced?'Play decorative animations':'Pause decorative animations');button.title=button.getAttribute('aria-label');button.textContent=reduced?'▷':'Ⅱ';button.disabled=systemMotion.matches;document.dispatchEvent(new Event('rr-motion-change'));}
applyMotion();document.querySelector('#motion-toggle').addEventListener('click',()=>{motionPaused=!motionPaused;applyMotion();try{localStorage.setItem('rr-motion',motionPaused?'paused':'playing');}catch{}toast(motionPaused?'Decorative animations paused':'Decorative animations enabled');});systemMotion.addEventListener('change',applyMotion);
window.addEventListener('hashchange',()=>{if(data){render();window.scrollTo({top:0,behavior:'instant'});}});
async function boot(){try{const response=await fetch('./assets/data.json');if(!response.ok)throw new Error('Data unavailable');data=await response.json();if(data.players.length!==249)throw new Error('Unexpected data schema');room=createSelectionRoom(data,{onInspect:openPlayer,onCompare:comparePlayer,notify:toast,shouldReduceMotion:isMotionReduced});render();}catch{main.innerHTML='<section class="card"><h1>The analysis could not load.</h1><p class="subtitle">Serve the dist folder over HTTP and check that assets/data.json is available.</p><button class="button button-pink margin-top" id="retry">Try again ↻</button></section>';document.querySelector('#retry').addEventListener('click',boot);}}
boot();
